def evaluate_checks(checks, observation):
    import math
    if observation.get('build_status') == 'failed' or observation.get('render_status') == 'failed':
        return {'blocking_defect': True, 'checks': [dict(rule_id=c['rule_id'], path=c['measurement_path'], status='blocked') for c in checks]}
    results=[]
    for c in checks:
        m=observation.get('measurements',{}).get(c['measurement_path'])
        r=dict(rule_id=c['rule_id'],path=c['measurement_path'])
        if not m: r['status']='not_assessed'
        elif m.get('execution')!='observed':r['status']='not_executed'
        elif m.get('method') not in c['accepted_methods'] or not m.get('evidence'):r['status']='unscorable'
        else:
            a,e,op=m.get('value'),c['expected'],c['operator']
            try:
                if op=='eq':ok=a==e
                elif op=='near':ok=math.isfinite(float(a)) and abs(float(a)-float(e))<=c['tolerance']
                elif op=='contains_all':ok=all(v in a for v in e)
                elif op=='gte':ok=float(a)>=float(e)
                elif op=='rgb_near':ok=len(a)==3 and max(abs(int(x)-int(y)) for x,y in zip(a,e))<=c['tolerance']
                else:raise ValueError('unknown operator')
                r.update(status='passed' if ok else 'failed',actual=a,expected=e,method=m['method'],evidence=m['evidence'])
            except (TypeError,ValueError,KeyError):r['status']='unscorable'
        results.append(r)
    return {'blocking_defect':False,'checks':results}
